package com.gk.jobhelper.controller;
import com.gk.jobhelper.common.ApiResponse;import com.gk.jobhelper.dto.*;import com.gk.jobhelper.service.*;import java.util.*;import javax.validation.Valid;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/recruitment") public class RecruitmentController {private final RecruitmentDiscoveryService discovery;private final RecruitmentNoticeService notices;private final RecruitmentDetailService details;private final RecruitmentPositionService positions;private final RecruitmentNoticeImageService images;private final RecruitmentQualificationMatchService qualification;public RecruitmentController(RecruitmentDiscoveryService d,RecruitmentNoticeService n,RecruitmentDetailService s,RecruitmentPositionService p,RecruitmentNoticeImageService i,RecruitmentQualificationMatchService q){discovery=d;notices=n;details=s;positions=p;images=i;qualification=q;}@PostMapping("/discovery")public ApiResponse<RecruitmentDiscoveryResult> discovery(){return ApiResponse.ok(discovery.discoverAll());}@GetMapping("/notices")public ApiResponse<PageVO<RecruitmentNoticeVO>> page(@RequestParam(required=false)String status,@RequestParam(required=false)String sourceCode,@RequestParam(required=false)String keyword,@RequestParam(defaultValue="1")int page,@RequestParam(defaultValue="20")int pageSize){return ApiResponse.ok(notices.page(status,sourceCode,keyword,page,pageSize));}@PostMapping("/notices/batch-delete")public ApiResponse<Void> batchDelete(@RequestBody List<Long> ids){notices.delete(ids);return ApiResponse.ok();}@GetMapping("/notices/{id}")public ApiResponse<RecruitmentNoticeVO> detail(@PathVariable Long id){return ApiResponse.ok(notices.detail(id));}@PostMapping("/notices/{id}/fetch-detail")public ApiResponse<RecruitmentDetailFetchResponse> fetchDetail(@PathVariable Long id){return ApiResponse.ok(details.fetch(id));}@PostMapping("/notices/{id}/extract-positions")public ApiResponse<RecruitmentPositionExtractionResponse> extract(@PathVariable Long id){return ApiResponse.ok(positions.extract(id));}@PostMapping("/notices/{id}/extract-body-positions")public ApiResponse<RecruitmentPositionExtractionResponse> extractBody(@PathVariable Long id){return ApiResponse.ok(positions.extractBody(id));}@GetMapping("/positions/filter-options")public ApiResponse<RecruitmentPositionFilterOptionsVO> filterOptions(){return ApiResponse.ok(positions.filterOptions());}@GetMapping("/positions")public ApiResponse<RecruitmentPositionLibraryPageVO> positionLibrary(@RequestParam(required=false)String keyword,@RequestParam(required=false)String location,@RequestParam(required=false)String organization,@RequestParam(required=false)String education,@RequestParam(required=false)String major,@RequestParam(required=false)Long noticeId,@RequestParam(required=false)String matchStatus,@RequestParam(defaultValue="1")int page,@RequestParam(defaultValue="20")int pageSize){return ApiResponse.ok(positions.page(keyword,location,organization,education,major,noticeId,matchStatus,page,pageSize));}@PostMapping("/positions/{id}/match")public ApiResponse<RecruitmentMatchResultVO> match(@PathVariable Long id){return ApiResponse.ok(qualification.match(id));}@GetMapping("/positions/{id}/match")public ApiResponse<RecruitmentMatchResultVO> matchDetail(@PathVariable Long id){return ApiResponse.ok(qualification.detail(id));}@PostMapping("/notices/{id}/match")public ApiResponse<List<RecruitmentMatchResultVO>> matchNotice(@PathVariable Long id){return ApiResponse.ok(qualification.matchNotice(id));}@PostMapping("/matches/rebuild")public ApiResponse<Map<String,Long>> rebuildMatches(){return ApiResponse.ok(qualification.rebuild());}@GetMapping("/notices/{id}/image")public ResponseEntity<byte[]> image(@PathVariable Long id,@RequestParam String url){RecruitmentNoticeImageService.Image image=images.load(id,url);return ResponseEntity.ok().contentType(MediaType.parseMediaType(image.type)).body(image.bytes);}@GetMapping("/notices/{id}/positions")public ApiResponse<List<RecruitmentPositionVO>> positions(@PathVariable Long id){return ApiResponse.ok(positions.list(id));}@GetMapping("/positions/{id}")public ApiResponse<RecruitmentPositionVO> position(@PathVariable Long id){return ApiResponse.ok(positions.detail(id));}@PutMapping("/notices/{id}/status")public ApiResponse<Void> status(@PathVariable Long id,@Valid @RequestBody RecruitmentNoticeStatusRequest request){notices.updateStatus(id,request.getStatus());return ApiResponse.ok();}@PostMapping("/notices/{id}/view")public ApiResponse<Void> view(@PathVariable Long id){notices.view(id);return ApiResponse.ok();}}
